let lenis: Lenis | null = null;

function initLenis() {
  if (lenis) return lenis; // biar ga double init

  lenis = new Lenis({
    lerp: 0.1,
    wheelMultiplier: 1.25,
  });

  // Initialize a new Lenis instance for smooth scrolling
  // lenis = new Lenis();

  // Synchronize Lenis scrolling with GSAP's ScrollTrigger plugin
  // lenis.on('scroll', ScrollTrigger.update);

  // Add Lenis's requestAnimationFrame (raf) method to GSAP's ticker
  // This ensures Lenis's smooth scroll animation updates on each GSAP tick

  // gsap.ticker.add((time) => {
  //   lenis.raf(time * 1000); // Convert time from seconds to milliseconds
  // });

  // Disable lag smoothing in GSAP to prevent any delay in scroll animations
  // gsap.ticker.lagSmoothing(0);

  // function raf(time) {
  //   lenis.raf(time);
  //   requestAnimationFrame(raf);
  // }

  // requestAnimationFrame(raf);
  lenis.on('scroll', ScrollTrigger.update),
    gsap.ticker.add((t) => {
      lenis.raf(1e3 * t);
    }),
    (window.lenis = lenis),
    gsap.ticker.lagSmoothing(500, 33);
  window.__lenis = lenis; // optional kalau mau akses global

  window.addEventListener('load', () => {
    lenis.resize();
    ScrollTrigger.refresh();
  });

  return lenis;
}

// getter kalau mau pakai di file lain
function getLenis() {
  return lenis;
}
function scrambleTextOnce(target, { isLoop = false, onComplete = null } = {}) {
  const scrambleChars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  const scrambleDuration = 1.5;
  const delayBetweenLoops = 5;
  const originalText = target.dataset.original || target.textContent;
  target.dataset.original = originalText;

  let progress = 0;
  const interval = 30;

  const scrambleInterval = setInterval(() => {
    const scrambled = originalText
      .split('')
      .map((char, i) => {
        if (char === ' ') return ' ';
        if (i < progress) return char;
        return scrambleChars.charAt(Math.floor(Math.random() * scrambleChars.length));
      })
      .join('');

    target.textContent = scrambled;
    progress++;

    if (progress > originalText.length) {
      clearInterval(scrambleInterval);
      target.textContent = originalText;

      if (typeof onComplete === 'function') onComplete();

      if (isLoop) {
        gsap.delayedCall(delayBetweenLoops, () => {
          scrambleTextOnce(target, { isLoop, onComplete });
        });
      }
    }
  }, interval);
}

// Initialize all scramble text
function initScrambleText() {
  const hero = document.querySelector('.tittle-text.is-hero');
  const others = document.querySelectorAll('[scramble]');

  if (hero) {
    scrambleTextOnce(hero, {
      isLoop: false,
      onComplete: () => {
        scrambleTextOnce(hero, { isLoop: true });
      },
    });
  }

  others.forEach((el) => {
    ScrollTrigger.create({
      trigger: el,
      start: 'top 90%',
      once: true,
      onEnter: () => {
        scrambleTextOnce(el, { isLoop: true });
      },
    });
  });
}

function splitLines({ scope = document } = {}) {
  const splitElements = scope.querySelectorAll('[data-split-lines]');

  splitElements.forEach((container) => {
    let elements = [];
    const splitRefs = [];
    const lines = [];

    const delay = parseFloat(container.getAttribute('data-delay')) || 0;
    const scrollAttr = container.getAttribute('data-scroll');
    const animateOnScroll = scrollAttr !== 'false'; // default: true

    // Jika elemen punya data-copy-wrapper → targetkan anak-anaknya
    if (container.hasAttribute('data-copy-wrapper')) {
      elements = Array.from(container.children);
    } else {
      elements = [container];
    }

    elements.forEach((element) => {
      const split = SplitText.create(element, {
        type: 'lines',
        mask: 'lines',
        linesClass: 'line++',
        lineThreshold: 0.1,
      });

      splitRefs.push(split);

      // Tangani text-indent agar tidak hilang
      const computedStyle = window.getComputedStyle(element);
      const { textIndent } = computedStyle;
      if (textIndent && textIndent !== '0px') {
        if (split.lines.length > 0) {
          split.lines[0].style.paddingLeft = textIndent;
        }
        element.style.textIndent = '0';
      }

      lines.push(...split.lines);
    });

    // Set posisi awal: turun 100%
    gsap.set(lines, { y: '100%' });

    const animationProps = {
      y: '0%',
      duration: 1,
      stagger: 0.1,
      ease: 'power4.out',
      delay,
    };

    if (animateOnScroll) {
      gsap.to(lines, {
        ...animationProps,
        scrollTrigger: {
          trigger: container,
          start: 'top 90%',
          once: true,
        },
      });
    } else {
      gsap.to(lines, animationProps);
    }

    // Optional: return fungsi cleanup
    return () => splitRefs.forEach((s) => s?.revert());
  });
}

function initSplitHead() {
  const splitTargets = document.querySelectorAll('[data-heading]');
  if (!splitTargets.length) return;

  splitTargets.forEach((el) => {
    if (!el || typeof el !== 'object' || !el.textContent.trim()) return;

    const split = new SplitText(el, {
      type: 'chars, words, lines',
      mask: 'words',
      wordsClass: 'word',
      charsClass: 'char',
      linesClass: 'line',
    });

    gsap.set(split.chars, { yPercent: 101 });

    ScrollTrigger.create({
      trigger: el,
      start: 'top 90%',
      markers: false,
      once: true,
      onEnter: () => {
        gsap.to(split.chars, {
          yPercent: 0,
          duration: 1.25,
          ease: 'primary-ease-out',
          stagger: {
            amount: 0.2,
            from: 'start',
          },
        });
      },
    });
  });
}

function imgReveal() {
  const content = document.querySelector('.work-content');
  if (!content) return;

  const imgWraps = content.querySelectorAll('.work-img-wrap');
  imgWraps.forEach((wrap) => {
    const img = wrap.querySelector('img');
    if (!img) return;

    gsap.set(img, { scale: 1.25 });
    gsap.set(wrap, { clipPath: 'inset(0% 0% 100% 0%)' });

    ScrollTrigger.create({
      trigger: wrap,
      start: 'top 90%',
      once: true,
      onEnter: () => {
        gsap.to(wrap, {
          clipPath: 'inset(0% 0% 0% 0%)',
          duration: 0.8,
          ease: 'custom',
        });
        gsap.to(img, {
          scale: 1,
          duration: 0.8,
          ease: 'custom',
        });
      },
    });
  });
}

function footerReveal() {
  const footer = document.querySelector('footer');
  if (!footer) return;

  const logo = footer.querySelector('.footer-logo-bottom');
  const img = logo?.querySelector('.footer-logo');
  if (!logo || !img) return;
  gsap.set(logo, { clipPath: 'inset(100% 0% 0% 0%)' });
  gsap.set(img, { scale: 1.25 });
  ScrollTrigger.create({
    trigger: logo,
    start: 'top 90%',
    once: true,
    onEnter: () => {
      gsap.to(logo, {
        clipPath: 'inset(0% 0% 0% 0%)',
        duration: 1.25,
        ease: 'custom',
      });
      gsap.to(img, {
        scale: 1,
        duration: 1.25,
        ease: 'custom',
      });
    },
  });
}

function initServiceHover() {
  const imgWrap = document.querySelector('.service-img-wrap') as HTMLElement;
  if (!imgWrap) return;
  const hoverWrap = document.querySelector('.service-hover-wrap') as HTMLElement;
  const imgEl = imgWrap.querySelector('img') as HTMLImageElement;
  const items = document.querySelectorAll('.service-item');
  const serviceList = document.querySelector('.service-list') as HTMLElement;

  let mouseX = 0,
    mouseY = 0,
    prevMouseX = 0;
  let velX = 0;
  let lerpX = 0,
    lerpY = 0;
  let isHovering = false;
  let cleanupTimeout: ReturnType<typeof setTimeout> | null = null;
  let moveTimer: ReturnType<typeof setTimeout> | null = null;
  let mouseTravel = 0;
  let lastMouseX = 0;

  const OFFSET_X = 0;
  const OFFSET_Y = 0;
  const LERP_SPEED = 0.1;
  const MAX_ROTATE = 14;
  const VEL_SMOOTH = 0.85;
  const CLEANUP_DELAY = 200;

  // Preload semua image saat init — supaya src swap tidak ada jeda load
  const allSrcs: string[] = [];
  items.forEach((item) => {
    const src = item.getAttribute('data-hover-img');
    if (src) {
      allSrcs.push(src);
      const preloadImg = new Image();
      preloadImg.src = src;
    }
  });

  // Init
  gsap.set(imgWrap, { autoAlpha: 0, x: 0, y: 0 });

  function lerp(a: number, b: number, t: number) {
    return a + (b - a) * t;
  }

  function cancelCleanup() {
    if (cleanupTimeout) {
      clearTimeout(cleanupTimeout);
      cleanupTimeout = null;
    }
  }

  function scheduleCleanup() {
    cancelCleanup();
    cleanupTimeout = setTimeout(() => {
      if (isHovering) return;
      gsap.to(imgWrap, {
        autoAlpha: 0,
        duration: 0.2,
        ease: 'power2.out',
      });
    }, CLEANUP_DELAY);
  }

  // rAF loop jalan terus — tidak start stop
  function loop() {
    // Lerp velX ke 0 — rotate melambat gradual, tidak snap
    velX = lerp(velX, mouseX - prevMouseX, 1 - VEL_SMOOTH);

    lerpX = lerp(lerpX, mouseX + OFFSET_X, LERP_SPEED);
    lerpY = lerp(lerpY, mouseY + OFFSET_Y, LERP_SPEED);

    const rotate = Math.max(-MAX_ROTATE, Math.min(MAX_ROTATE, velX * 1.8));

    gsap.set(imgWrap, {
      x: lerpX,
      y: lerpY,
      rotate,
      xPercent: -50,
      yPercent: -50,
    });

    prevMouseX = mouseX;
    requestAnimationFrame(loop);
  }

  requestAnimationFrame(loop);

  document.addEventListener('mousemove', (e) => {
    mouseX = e.clientX;
    mouseY = e.clientY;

    // if (moveTimer) clearTimeout(moveTimer);
    // moveTimer = setTimeout(() => {
    //   velX = 0;
    // }, 100);
  });

  items.forEach((item) => {
    item.addEventListener('mouseenter', () => {
      cancelCleanup();
      isHovering = true;

      const src = item.getAttribute('data-hover-img') ?? '';

      // Langsung ganti src — tidak perlu fade out dulu karena sudah preloaded
      imgEl.src = src;

      gsap.to(imgEl, {
        autoAlpha: 1,
        duration: 0.3,
        ease: 'power2.out',
        overwrite: true,
      });

      gsap.to(imgWrap, {
        autoAlpha: 1,
        duration: 0.3,
        ease: 'power2.out',
        overwrite: true,
      });
    });

    item.addEventListener('mouseleave', () => {
      isHovering = false;
      scheduleCleanup();
    });
  });
}

function initStory() {
  const stickyCards = document.querySelectorAll('.story-item');

  stickyCards.forEach((card, index) => {
    // Pin setiap card kecuali yang terakhir
    if (index < stickyCards.length - 1) {
      ScrollTrigger.create({
        trigger: card,
        start: 'top top',
        endTrigger: stickyCards[stickyCards.length - 1],
        end: 'top top',
        pin: true,
        pinSpacing: false,
      });
    }

    // Scale + rotate saat card berikutnya naik
    if (index < stickyCards.length - 1) {
      ScrollTrigger.create({
        trigger: stickyCards[index + 1],
        start: 'top bottom',
        end: 'top top',
        onUpdate: (self) => {
          const progress = self.progress;

          gsap.set(card, {
            scale: 1 - progress * 0.25,
            rotation: (index % 2 === 0 ? 5 : -5) * progress,
            '--after-opacity': progress,
          });
        },
      });
    }
  });
}

function initLogoReveal() {
  const paths = document.querySelectorAll('.hero-logo-svg path');

  // Setup setiap path untuk draw effect
  paths.forEach((path) => {
    const length = (path as SVGPathElement).getTotalLength();

    gsap.set(path, {
      strokeDasharray: length,
      strokeDashoffset: length,
      fill: 'transparent',
      stroke: '#2B2B2B',
      strokeWidth: 2,
    });
  });

  const tl = gsap.timeline();

  // Draw stroke dulu
  tl.to(paths, {
    strokeDashoffset: 0,
    duration: 1.5,
    ease: 'power2.inOut',
    stagger: 0.15,
  })
    // Lalu fill masuk, stroke fade out
    .to(
      paths,
      {
        fill: '#2B2B2B',
        duration: 0.5,
        ease: 'power2.out',
        // stagger: 0.1,
      },
      '-=0.3'
    )
    .to(
      paths,
      {
        stroke: 'transparent',
        strokeWidth: 0,
        duration: 0.5,
        ease: 'none',
        // stagger: 0.1,
      },
      '<'
    );

  return tl;
}

function initLoad() {
  const wrapper = document.querySelector('.hero-wrapper.is-home');
  if (!wrapper) return;
  const nav = document.querySelector('.navbar');
  const brand = nav?.querySelector('.nav-brand');
  const menu = nav?.querySelector('.nav-menu');
  const links = menu?.querySelectorAll('.nav-link');
  const right = nav?.querySelector('.nav-right');

  gsap.set(brand, { autoAlpha: 0, x: -16 });
  gsap.set(links, { autoAlpha: 0, x: -16 });
  gsap.set(right, { autoAlpha: 0, x: 16 });

  const text = wrapper.querySelector('.text-16');

  const splitText = new SplitText(text, {
    type: 'lines',
    linesClass: 'line++',
    mask: 'lines',
  });

  gsap.set(splitText.lines, { yPercent: 110 });

  const tl = gsap.timeline({ paused: true });

  tl.to(brand, {
    autoAlpha: 1,
    x: 0,
    duration: 0.8,
    ease: 'power2.out',
  })
    .to(
      links,
      {
        autoAlpha: 1,
        x: 0,
        ease: 'power2.out',
        duration: 0.8,
        stagger: 0.03,
      },
      '<'
    )
    .to(
      right,
      {
        autoAlpha: 1,
        x: 0,
        ease: 'power2.out',
        duration: 0.8,
      },
      '<'
    )
    .to(
      splitText.lines,
      {
        yPercent: 0,
        duration: 1.25,
        ease: 'power3.out',
        stagger: {
          amount: 0.2,
          from: 'start',
        },
      },
      '<'
    );

  // Logo reveal dulu, onComplete baru play timeline utama
  // const logoTl = initLogoReveal();
  // logoTl.eventCallback('onComplete', () => {
  //   tl.play();
  // });

  tl.play();
}

function initCursor() {
  const wrapper = document.querySelector('.custom-cursor-wrapper') as HTMLElement;
  const cursor = document.querySelector('.custom-cursor') as HTMLElement;

  if (!wrapper || !cursor) return;

  let mouseX = 0,
    mouseY = 0;
  let posX = 0,
    posY = 0;
  const speed = 0.12;

  gsap.set(cursor, { xPercent: -50, yPercent: -50 });

  function loop() {
    posX += (mouseX - posX) * speed;
    posY += (mouseY - posY) * speed;

    gsap.set(cursor, { x: posX, y: posY });

    requestAnimationFrame(loop);
  }

  requestAnimationFrame(loop);

  document.addEventListener('mousemove', (e) => {
    mouseX = e.clientX;
    mouseY = e.clientY;
  });

  // Hide saat keluar window
  document.addEventListener('mouseleave', () => {
    gsap.to(cursor, { autoAlpha: 0, duration: 0.3 });
  });

  document.addEventListener('mouseenter', () => {
    gsap.to(cursor, { autoAlpha: 1, duration: 0.3 });
  });
}

function workHover() {
  const wrapper = document.querySelector('.work-content');
  if (!wrapper) return;

  const items = wrapper.querySelectorAll('.work-item');

  items.forEach((item) => {
    const imgWrap = item.querySelector('.work-img-wrap');
    const img = imgWrap?.querySelector('img');
    // const title = imgWrap?.querySelector('.text-24');
    if (!imgWrap || !img) return;

    // const splitTitle = new SplitText(title, {
    //   type: 'chars',
    //   charsClass: 'char',
    //   mask: 'chars',
    // });

    gsap.set(img, { scale: 1 });
    // gsap.set(splitTitle.chars, { y: '100%' });
    gsap.set(imgWrap, { filter: 'grayscale(0%)' }); // default semua normal

    item.addEventListener('mouseenter', () => {
      // Semua imgWrap jadi grayscale kecuali yang dihover
      items.forEach((otherItem) => {
        const otherImgWrap = otherItem.querySelector('.work-img-wrap');
        if (!otherImgWrap) return;

        if (otherItem === item) {
          gsap.to(otherImgWrap, { filter: 'grayscale(0%)', duration: 0.4, ease: 'power2.out' });
        } else {
          gsap.to(otherImgWrap, { filter: 'grayscale(100%)', duration: 0.4, ease: 'power2.out' });
        }
      });

      gsap.to(img, { scale: 1.1, duration: 0.5, ease: 'power2.out' });
      // gsap.to(splitTitle.chars, {
      //   y: '0%',
      //   duration: 0.4,
      //   ease: 'power3.out',
      //   stagger: { each: 0.02, from: 'start' },
      // });
    });

    item.addEventListener('mouseleave', () => {
      // Reset semua ke grayscale 0
      items.forEach((otherItem) => {
        const otherImgWrap = otherItem.querySelector('.work-img-wrap');
        if (!otherImgWrap) return;
        gsap.to(otherImgWrap, { filter: 'grayscale(0%)', duration: 0.4, ease: 'power2.out' });
      });

      gsap.to(img, { scale: 1, duration: 0.5, ease: 'power2.out' });
      // gsap.to(splitTitle.chars, {
      //   y: '100%',
      //   duration: 0.4,
      //   ease: 'power3.out',
      //   stagger: 0.02,
      // });
    });
  });
}

function navColorChange() {
  const navbar = document.querySelector('.navbar');
  const sections = document.querySelectorAll('[dark-section]');

  if (!navbar || !sections.length) return;

  const navHeight = navbar.offsetHeight / 2;

  sections.forEach((section) => {
    ScrollTrigger.create({
      trigger: section,
      start: `top ${navHeight}px`,
      end: `bottom ${navHeight}px`,

      onEnter: () => {
        navbar.classList.remove('is-dark');
        // navMobile.classList.remove('is-dark');
      },

      onEnterBack: () => {
        navbar.classList.remove('is-dark');
        // navMobile.classList.remove('is-dark');
      },

      onLeave: () => {
        navbar.classList.add('is-dark');
        // navMobile.classList.add('is-dark');
      },

      onLeaveBack: () => {
        navbar.classList.add('is-dark');
        // navMobile.classList.add('is-dark');
      },
    });
  });
}

