function initApp() {
  // const mm = gsap.matchMedia();
  const windowWidth = window.innerWidth;
  const mobileBreakpoint = 768;
  const isMobile = windowWidth <= mobileBreakpoint;

  initLenis();
  window.lenis = getLenis();
  initSplitHead();
  splitLines();
  initAos();
  initStaggeredAos();
  imgReveal();
  // footerReveal();
  initScrambleText();
  navColorChange();

  // main

  if (!isMobile) {
    // Desktop specific code here
    initServiceHover();
    //initStory();

    initSectionOverlapPrev();
    initCursor();
    workHover();

    ScrollTrigger.refresh();
  }

  if (isMobile) {
    // Mobile specific code here
  }

  function refreshAll() {
    ScrollTrigger.refresh();
    // Lenis perlu tau total height baru
    lenis.resize(); // ← ini yang sering dilupakan
  }

  // Pasang di semua image load listener
  let refreshTimeout;
  document.querySelectorAll('img[loading="lazy"]').forEach((img) => {
    if (img.complete) return;
    img.addEventListener(
      'load',
      () => {
        clearTimeout(refreshTimeout);
        refreshTimeout = setTimeout(refreshAll, 100);
      },
      { once: true }
    );
  });
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => {
    initApp();
    initLoad();
  });
} else {
  initApp();
  initLoad();
}
